CREATE TABLE feature_snapshots(hash TEXT PRIMARY KEY, fixture_id TEXT NOT NULL REFERENCES fixtures(id), feature_version TEXT NOT NULL, information_cutoff_date TEXT NOT NULL, payload TEXT NOT NULL);
INSERT OR IGNORE INTO feature_snapshots(hash,fixture_id,feature_version,information_cutoff_date,payload) SELECT snapshot_hash,fixture_id,feature_version,information_cutoff_date,payload FROM features;
CREATE TRIGGER immutable_feature_snapshot_update BEFORE UPDATE ON feature_snapshots BEGIN SELECT RAISE(ABORT,'feature_snapshot_immutable'); END;
CREATE TRIGGER immutable_feature_snapshot_delete BEFORE DELETE ON feature_snapshots BEGIN SELECT RAISE(ABORT,'feature_snapshot_immutable'); END;
CREATE TRIGGER archive_new_features AFTER INSERT ON features BEGIN INSERT OR IGNORE INTO feature_snapshots(hash,fixture_id,feature_version,information_cutoff_date,payload) VALUES(NEW.snapshot_hash,NEW.fixture_id,NEW.feature_version,NEW.information_cutoff_date,NEW.payload); END;
CREATE TRIGGER archive_updated_features AFTER UPDATE ON features BEGIN INSERT OR IGNORE INTO feature_snapshots(hash,fixture_id,feature_version,information_cutoff_date,payload) VALUES(NEW.snapshot_hash,NEW.fixture_id,NEW.feature_version,NEW.information_cutoff_date,NEW.payload); END;
CREATE TRIGGER reject_feature_hash_collision_insert BEFORE INSERT ON features WHEN EXISTS(SELECT 1 FROM feature_snapshots WHERE hash=NEW.snapshot_hash AND (payload<>NEW.payload OR fixture_id<>NEW.fixture_id)) BEGIN SELECT RAISE(ABORT,'feature_hash_collision'); END;
CREATE TRIGGER reject_feature_hash_collision_update BEFORE UPDATE ON features WHEN EXISTS(SELECT 1 FROM feature_snapshots WHERE hash=NEW.snapshot_hash AND (payload<>NEW.payload OR fixture_id<>NEW.fixture_id)) BEGIN SELECT RAISE(ABORT,'feature_hash_collision'); END;
CREATE TRIGGER prediction_requires_archived_features BEFORE INSERT ON predictions WHEN NOT EXISTS(SELECT 1 FROM feature_snapshots WHERE hash=NEW.feature_snapshot_hash AND fixture_id=NEW.fixture_id AND information_cutoff_date=NEW.information_cutoff_date) BEGIN SELECT RAISE(ABORT,'missing_feature_snapshot'); END;
